from typing import Annotated

import cyclopts
from cyclopts import Parameter
from cyclopts.validators import Number

app = cyclopts.App()


@app.command
def serve(
    port: Annotated[
        int,
        Parameter(validator=Number(gte=1024, lte=65535)),
    ],
):
    print(f"Serving on port {port}")


if __name__ == "__main__":
    app()
